import{_ as n,l as s,o as e,c as i,v as t,p as r,x as l,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"SFT 打包与掩码","description":"","frontmatter":{"title":"SFT 打包与掩码","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sft-packing-mask.md","filePath":"llm/sft-packing-mask.md","lastUpdated":1789023840000}'),h={name:"llm/sft-packing-mask.md"};function E(m,a,f,k,A,_){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="sft-打包与掩码" tabindex="-1">SFT 打包与掩码 <a class="header-anchor" href="#sft-打包与掩码" aria-label="Permalink to &quot;SFT 打包与掩码&quot;">​</a></h1><div class="epigraph"><p>把短指令首尾相接可以喂满上下文窗口，但注意力与损失必须仍按样本切开；否则下一条的提示会成为上一条回复的合法上文。</p><footer>—— 打包来自预训练的序列拼接习惯；SFT 要额外保住样本边界上的因果隔离与仅回复损失</footer></div><p><a href="/llm/response-only-loss">上一课</a>把梯度限制在助手 token 上。实现若按「一条样本一个序列」padding 到最大长度，短指令会让有效 token 占比掉到 20% 以下，<a href="/llm/full-sft-hparams">全参批次</a>名存实亡。打包（packing）把多条样本拼进同一长度 \\(L\\) 的缓冲，提高硬件利用率。缺口是：拼上之后，<a href="/llm/response-only-loss">仅回复损失</a>与注意力掩码必须一起改，否则样本互相污染。本课写隔离契约，不把长上下文外推（<a href="/llm/long-context-finetune">后课</a>）提前写进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>预训练打包网页时，文档边界用特殊 token 断开，有的实现仍允许跨文档attend——网页本来就是杂糅流。SFT 每条样本是独立的指令事件：用户 A 的问题不得成为用户 B 回答的条件。若打包后仍用下三角满掩码，位置 \\(t\\) 属于样本 \\(i\\) 的回复，却能看见样本 \\(i-1\\) 的完成，模型会学到「抄上一包里的答案」，评测单条时这条捷径消失，表现为训练 NLL 很好、推理变傻。</p><p>第二条污染在损失：拼接后 <code>labels</code> 若只按「最后一个助手段」书写，中间样本的回复被当成人为前缀而掩码，或反过来把下一条的用户段解掩码。打包不是把 <code>input_ids</code> concat 完就结束；它是布局问题，掩码是正确性。</p><h3 id="有效批次按-token-隔离按样本" tabindex="-1">有效批次按 token，隔离按样本 <a class="header-anchor" href="#有效批次按-token-隔离按样本" aria-label="Permalink to &quot;有效批次按 token，隔离按样本&quot;">​</a></h3><p><a href="/llm/full-sft-hparams">全参超参</a>要求有效批次按 token 计。打包提高每步 token 数，等价于在不加大微批次的前提下抬有效批次。但「每步多少 token」与「这些 token 是否跨样本可见」是两件事。只报 packing=true 而不报文档掩码，无法复现，也无法解释角色泄漏。</p><p><span class="marginnote">FlashAttention 一类变长接口用 <code>cu_seqlens</code> 做样本内满因果、样本间断开，避免 padding 浪费。这是实现，不是新损失。逻辑上仍是：块对角因果掩码 + 仅回复 labels。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先把每条样本独立经<a href="/llm/chat-template">chat template</a>渲染，并打好仅回复 <code>labels</code>。再按长度贪心装进容量 \\(L\\) 的桶：装不下就新开一条打包序列。拼接处插入明确的分隔（EOS 或专用 pad），<strong>注意力在分隔处切断</strong>：样本 \\(i\\) 的位置不能 attend 到 \\(j\\neq i\\)。损失对分隔与 padding 忽略；各样本的回复掩码保持渲染时的定义，不要在 concat 后重算「最后一个 assistant」。</p><p>超长单条：截断策略要写清——截提示保回复、还是丢整条。截提示会改条件，等于换任务；丢整条更干净，但会偏置短样本。两者都优于静默截断回复末尾（学一个不完整的结束）。</p>',12)),(e(),r(c,null,{default:l(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%8D%95%E6%9D%A1%E6%B8%B2%E6%9F%93%20%2B%20%E4%BB%85%E5%9B%9E%E5%A4%8D%20labels%22%5D%20--%3E%20P%5B%22%E6%8C%89%E9%95%BF%E5%BA%A6%E8%A3%85%E5%85%A5%E7%AA%97%E5%8F%A3%20L%22%5D%0A%20%20P%20--%3E%20A%5B%22%E5%9D%97%E5%AF%B9%E8%A7%92%E5%9B%A0%E6%9E%9C%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20P%20--%3E%20L2%5B%22labels%20%E4%BB%8D%E6%8C%89%E5%8E%9F%E6%A0%B7%E6%9C%AC%E5%9B%9E%E5%A4%8D%22%5D%0A%20%20A%20--%3E%20U%5B%22%E4%B8%80%E6%AC%A1%E6%9B%B4%E6%96%B0%E7%9A%84%E6%9C%89%E6%95%88%20token%22%5D%0A%20%20L2%20--%3E%20U%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与预训练衔接：若基座预训练用了打包，SFT 继续打包可减少分布偏移；但预训练未必切断文档注意力。SFT 默认更严：切断。不要为了多几个 token 把隔离关掉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>块对角掩码使样本 \\(i\\) 的回复位置上，\\(p(x_t\\mid x_{\\lt t})\\) 的条件只含本条前缀。梯度因此只沿本条计算图回传。若不断开，条件里出现异质前缀（别人的系统提示、别人的答案），注意力把这些键当捷径：短回复尤其爱抄包内邻近完成，因为位置近、标记相似。这会表现为<a href="/llm/chat-template">模板</a>「没问题」但多卡训练偶发串话——串的是包内邻居，不是模板写错。</p><p>打包还改变长度分布。未打包时，短样本被 pad，损失若错误地在 pad 上计（未忽略），梯度被 pad token 稀释。打包后 pad 少了，同样的名义学习率下回复 token 的更新更猛。因此打开 packing 应视为有效数据密度上升，需要重新确认 \\(\\eta\\) 与步数，而不是「免费加速」。</p><p><span class="marginnote"><a href="/llm/lora">LoRA</a> 不改变隔离需求。适配器容量小，更容易记住包内捷径。脏打包 + LoRA 是常见过拟合组合。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>打包不适合必须保持「单条超长、不许切断注意力」的任务，例如要学满窗口依赖的长上下文 SFT——那是<a href="/llm/long-context-finetune">后课</a>用真实长序列或跳步位置，而不是把十条短指令拼成 32k。也不要把不同谱系（FLAN 短标签与 ShareGPT 长多轮）无权重地塞进同一包而不打来源：有效批次的任务混合会随长度偏置被长对话主导。</p><p>核对：随机抽一条打包序列，画出注意力允许的块、以及 <code>labels != ignore</code> 的位置，确认块与回复同属一条原始样本。能过这一可视化，再谈吞吐。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>打包提高 SFT 的 token 利用率，使有效批次接近名义窗口。</li><li>必须块对角切断注意力，并保持按样本的仅回复 <code>labels</code>。</li><li>不断开会导致包内抄答案；训练很好、单条推理变差。</li><li>打开 packing 会改变有效数据密度，学习率与步数可能要重扫。</li><li>超长样本的截断策略要写进配方；勿静默截断回复。</li><li>出处：预训练序列打包的工程习惯；SFT 侧的正确性约束来自样本独立性与仅回复目标，而非单独一篇「发明打包」的论文。</li></ul>',10))])}const T=n(h,[["render",E]]);export{B as __pageData,T as default};
